    (select month, category_key, round(total, 2) from public.v_period_totals where uid = 'golden-user' except select month, category_key, round(total, 2) from expected_period_totals)
    union all
    (select month, category_key, round(total, 2) from expected_period_totals except select month, category_key, round(total, 2) from public.v_period_totals where uid = 'golden-user')
  ) r;
  if diff is not null then raise exception 'v_period_totals differs from the TypeScript reference: %', diff; end if;
  select string_agg(r::text, '; ') into diff from (
    (select month, round(total_expenses, 2), round(total_income, 2), transaction_count from public.v_cash_flow_by_month where uid = 'golden-user' except select month, round(total_expenses, 2), round(total_income, 2), transaction_count from expected_cash_flow)
    union all
    (select month, round(total_expenses, 2), round(total_income, 2), transaction_count from expected_cash_flow except select month, round(total_expenses, 2), round(total_income, 2), transaction_count from public.v_cash_flow_by_month where uid = 'golden-user')
  ) r;
  if diff is not null then raise exception 'v_cash_flow_by_month differs from the TypeScript reference: %', diff; end if;
  select string_agg(r::text, '; ') into diff from (
    (select card_id, entries, round(total_received, 2), round(total_voided, 2), round(statement_credits, 2), round(rewards, 2) from public.v_cashback_history where uid = 'golden-user' except select card_id, entries, round(total_received, 2), round(total_voided, 2), round(statement_credits, 2), round(rewards, 2) from expected_cashback)
    union all
    (select card_id, entries, round(total_received, 2), round(total_voided, 2), round(statement_credits, 2), round(rewards, 2) from expected_cashback except select card_id, entries, round(total_received, 2), round(total_voided, 2), round(statement_credits, 2), round(rewards, 2) from public.v_cashback_history where uid = 'golden-user')
  ) r;
  if diff is not null then raise exception 'v_cashback_history differs from the TypeScript reference: %', diff; end if;
  select string_agg(r::text, '; ') into diff from (
    (select account_id, round(net, 2) from public.v_account_flows where uid = 'golden-user' except select account_id, round(net, 2) from expected_account_flows)
    union all
    (select account_id, round(net, 2) from expected_account_flows except select account_id, round(net, 2) from public.v_account_flows where uid = 'golden-user')
  ) r;
  if diff is not null then raise exception 'v_account_flows differs from the TypeScript reference: %', diff; end if;
end
$$;

rollback;

select 'read-model golden tests passed (views = TypeScript reference)' as result;
